render():
```js
function render(){
  tabs.forEach((t,i)=>{ const on=i===step; t.classList.toggle('is-active',on); t.setAttribute('aria-selected',on?'true':'false'); t.tabIndex = on?0:-1;});
  panes.forEach((p,i)=>p.classList.toggle('is-active',i===step));
  prevBtn.disabled = step===0;
  nextBtn.hidden = step===7;
  finishBtn.hidden = step!==7;
  progress.style.width = ((step+1)/8*100)+'%';
}
```
